// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        amount = bound(amount, 0, 1_000_000 ether);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        try c.withdrawAll(nonOwner) {} catch {}
        assertTrue(address(c).balance == balanceBefore);
    }
}
